/** The complete set of persistable attachment references. */
export const CHECKPOINT_ATTACHMENT_KINDS = [
  "task-attachment",
  "recovery-instruction",
  "context",
  "external-artifact-ref",
  "ledger-checkpoint",
] as const;

export type CheckpointAttachmentKind = (typeof CHECKPOINT_ATTACHMENT_KINDS)[number];

export type CheckpointAttachmentRepairState =
  | "missing-hash"
  | "invalid-hash"
  | "missing-owner"
  | "expired"
  | "conflict"
  | "valid";

export interface CheckpointAttachmentBinding {
  readonly kind: CheckpointAttachmentKind;
  readonly ref: string;
  readonly contentHash: string;
  readonly owner: string;
  /** Unix epoch milliseconds. */
  readonly expiresAt: number;
}

export interface PersistedCheckpointAttachmentBinding {
  readonly kind: string;
  readonly ref: string;
  readonly contentHash?: string | null;
  readonly owner?: string | null;
  readonly expiresAt?: number | string | null;
}

export interface CheckpointAttachmentRecoveryInput {
  readonly attachments?: readonly PersistedCheckpointAttachmentBinding[];
  readonly bindings?: readonly PersistedCheckpointAttachmentBinding[];
  readonly now?: number;
}

export interface RepairedCheckpointAttachmentBinding {
  readonly ref: string;
  readonly kind: string;
  readonly contentHash: string | null;
  readonly owner: string | null;
  readonly expiresAt: number | null;
  readonly state: CheckpointAttachmentRepairState;
  readonly recovered: boolean;
}

export interface CheckpointAttachmentRecoveryResult {
  readonly recovered: readonly RepairedCheckpointAttachmentBinding[];
  readonly repaired: readonly RepairedCheckpointAttachmentBinding[];
  readonly digest: string;
}

const SHA256_HEX = /^[0-9a-f]{64}$/;
const ALLOWED_KIND_SET: ReadonlySet<string> = new Set(CHECKPOINT_ATTACHMENT_KINDS);

function canonicalJson(value: unknown): string {
  if (value === null || typeof value !== "object") {
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map(canonicalJson).join(",")}]`;
  }
  const object = value as Record<string, unknown>;
  return `{${Object.keys(object)
    .sort()
    .map((key) => `${JSON.stringify(key)}:${canonicalJson(object[key])}`)
    .join(",")}}`;
}

function sha256(value: string): string {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

function isAllowedKind(value: string): value is CheckpointAttachmentKind {
  return ALLOWED_KIND_SET.has(value);
}

function parseExpiry(value: number | string | null | undefined): number | null {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : null;
  }
  if (typeof value === "string" && value.trim() !== "") {
    const parsed = Date.parse(value);
    return Number.isNaN(parsed) ? null : parsed;
  }
  return null;
}

function compareBindings(
  left: RepairedCheckpointAttachmentBinding,
  right: RepairedCheckpointAttachmentBinding,
): number {
  const leftKey = `${left.ref}\u0000${left.kind}\u0000${left.contentHash ?? ""}`;
  const rightKey = `${right.ref}\u0000${right.kind}\u0000${right.contentHash ?? ""}`;
  return leftKey < rightKey ? -1 : leftKey > rightKey ? 1 : 0;
}

function repairBinding(
  binding: PersistedCheckpointAttachmentBinding,
  now: number,
): RepairedCheckpointAttachmentBinding {
  const kind = typeof binding.kind === "string" ? binding.kind : "";
  const ref = typeof binding.ref === "string" ? binding.ref : "";
  const rawHash = typeof binding.contentHash === "string" ? binding.contentHash.trim() : "";
  const owner = typeof binding.owner === "string" && binding.owner.trim() !== "" ? binding.owner : null;
  const expiresAt = parseExpiry(binding.expiresAt);

  let state: CheckpointAttachmentRepairState;
  if (rawHash === "") {
    state = "missing-hash";
  } else if (!SHA256_HEX.test(rawHash)) {
    state = "invalid-hash";
  } else if (owner === null) {
    state = "missing-owner";
  } else if (expiresAt === null || expiresAt <= now) {
    state = "expired";
  } else if (!isAllowedKind(kind)) {
    state = "invalid-hash";
  } else {
    state = "valid";
  }

  const contentHash = rawHash !== "" && SHA256_HEX.test(rawHash) ? rawHash.toLowerCase() : null;
  return Object.freeze({
    ref,
    kind,
    contentHash,
    owner,
    expiresAt,
    state,
    recovered: state === "valid",
  });
}

/**
 * Recover persisted attachment references without mutating the input or performing
 * any external action. Conflicting occurrences are represented explicitly and
 * are never included in the recovered set.
 */
export function recoverCheckpointAttachmentBindings(
  input: CheckpointAttachmentRecoveryInput | readonly PersistedCheckpointAttachmentBinding[],
): CheckpointAttachmentRecoveryResult {
  const isArray = Array.isArray(input);
  const source: readonly PersistedCheckpointAttachmentBinding[] = isArray
    ? (input as readonly PersistedCheckpointAttachmentBinding[])
    : ((input as CheckpointAttachmentRecoveryInput).attachments ??
       (input as CheckpointAttachmentRecoveryInput).bindings ??
       []);
  const now = isArray
    ? Date.now()
    : typeof (input as CheckpointAttachmentRecoveryInput).now === "number" &&
        Number.isFinite((input as CheckpointAttachmentRecoveryInput).now)
      ? (input as CheckpointAttachmentRecoveryInput).now
      : Date.now();

  const repaired = source.map((binding) => repairBinding(binding, now));
  const firstByRef = new Map<string, RepairedCheckpointAttachmentBinding>();
  const conflicts = new Set<string>();

  for (const binding of repaired) {
    const first = firstByRef.get(binding.ref);
    if (first === undefined) {
      firstByRef.set(binding.ref, binding);
      continue;
    }
    if (
      first.contentHash !== binding.contentHash ||
      first.kind !== binding.kind ||
      first.owner !== binding.owner ||
      first.expiresAt !== binding.expiresAt
    ) {
      conflicts.add(binding.ref);
    }
  }

  const explicitlyRepaired = repaired.map((binding) => {
    if (!conflicts.has(binding.ref)) {
      return binding;
    }
    const first = firstByRef.get(binding.ref)!;
    return Object.freeze({
      ...first,
      state: "conflict" as const,
      recovered: false,
    });
  });

  const recovered = explicitlyRepaired
    .filter((binding) => binding.recovered)
    .sort(compareBindings);
  const sortedRepaired = [...explicitlyRepaired].sort(compareBindings);
  const digest = sha256(canonicalJson(sortedRepaired));

  return Object.freeze({
    recovered: Object.freeze(recovered),
    repaired: Object.freeze(sortedRepaired),
    digest,
  });
}

export const recoverAttachmentBindings = recoverCheckpointAttachmentBindings;

export function checkpointAttachmentRecoveryDigest(
  result: CheckpointAttachmentRecoveryResult,
): string {
  return sha256(canonicalJson(result.repaired));
}
